// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate, Easing } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

// Module-level font loading for Inter
const { fontFamily: interFontFamily } = loadInter();



export type ButtonClickAnimationProps = Record<string, any>;

const ButtonClickAnimation: React.FC<ButtonClickAnimationProps> = ({
  backgroundColor = "#030816",
  transparentBackground = false,
  durationInSeconds = 5,
  buttonText = "Book A Call Now",
  buttonColor = "#cdf2bf",
  textColor = "#030816",
  buttonWidthPercent = 85,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const finalBackgroundColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Timings (in frames)
  const buttonAppearStart = 10;
  const cursorApproachStart = 35;
  const clickStart = 70;
  const clickRelease = 74;
  const cursorExitStart = 85;

  // --- Button Animations ---
  // Entrance spring
  const buttonSpring = spring({
    frame: frame - buttonAppearStart,
    fps,
    config: { damping: 12, mass: 0.8, stiffness: 100 },
  });
  
  // Combine entrance scaling with click reaction
  const clickDownSpring = spring({
    frame: frame - clickStart,
    fps,
    config: { damping: 4, mass: 0.1, stiffness: 200 },
  });
  
  const clickUpSpring = spring({
    frame: frame - clickRelease,
    fps,
    config: { damping: 8, mass: 0.4, stiffness: 150 },
  });

  // Calculate composite button scale
  const buttonBaseScale = interpolate(buttonSpring, [0, 1], [0, 1], {
    extrapolateRight: "clamp",
  });
  const clickFactor = interpolate(clickDownSpring, [0, 1], [0, -0.08], { extrapolateRight: "clamp" }) +
                      interpolate(clickUpSpring, [0, 1], [0, 0.08], { extrapolateRight: "clamp" });
  const buttonScale = Math.max(0, buttonBaseScale + clickFactor);

  // --- Cursor Animations ---
  // Start off-canvas bottom-right, move to button click spot, then retreat
  const targetX = width * 0.70;
  const targetY = height * 0.53;
  const startX = width * 1.1;
  const startY = height * 1.1;
  const exitX = width * 0.95;
  const exitY = height * 1.2;

  const cursorX = interpolate(frame, 
    [cursorApproachStart, cursorApproachStart + 25, cursorExitStart, cursorExitStart + 25],
    [startX, targetX, targetX, exitX],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
      easing: Easing.bezier(0.25, 1, 0.5, 1),
    }
  );

  const cursorY = interpolate(frame, 
    [cursorApproachStart, cursorApproachStart + 25, cursorExitStart, cursorExitStart + 25],
    [startY, targetY, targetY, exitY],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
      easing: Easing.bezier(0.25, 1, 0.5, 1),
    }
  );

  // Cursor scaling to simulate physical "clicking down" action
  const cursorScale = interpolate(frame,
    [clickStart, clickStart + 3, clickRelease, clickRelease + 3],
    [1.1, 0.85, 0.85, 1.1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // --- Click Sparkle & Ring Effects ---
  const clickProgress = interpolate(frame, [clickStart, clickStart + 18], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const sparkOpacity = interpolate(clickProgress, [0, 0.1, 0.7, 1], [0, 1, 1, 0]);
  const sparkRadius = interpolate(clickProgress, [0, 1], [0, 50]);

  // Spark coordinate vectors
  const sparkAngles = [0, 45, 135, 180, 225, 270, 315];

  // --- Left-side accent burst (Top-Left corner of button) ---
  const leftAccentProgress = interpolate(frame, [buttonAppearStart + 8, buttonAppearStart + 28], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const leftAccentOpacity = interpolate(leftAccentProgress, [0, 0.1, 0.7, 1], [0, 1, 1, 0]);
  const leftAccentOffset = interpolate(leftAccentProgress, [0, 1], [5, 30]);

  return (
    <AbsoluteFill
      style={{
        backgroundColor: finalBackgroundColor,
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        fontFamily: interFontFamily,
        overflow: "hidden",
      }}
    >
      {/* Centered container to align button and accents accurately */}
      <div
        style={{
          position: "relative",
          width: `${buttonWidthPercent}%`,
          maxWidth: 900,
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          transition: "none",
        }}
      >
        {/* Left Accent Burst */}
        <div
          style={{
            position: "absolute",
            top: -30,
            left: -10,
            width: 80,
            height: 80,
            pointerEvents: "none",
            opacity: leftAccentOpacity,
            transition: "none",
          }}
        >
          {[-60, -25, 10].map((angle, idx) => {
            const rad = (angle * Math.PI) / 180;
            const x = Math.cos(rad) * leftAccentOffset;
            const y = Math.sin(rad) * leftAccentOffset;
            return (
              <div
                key={idx}
                style={{
                  position: "absolute",
                  left: "50%",
                  top: "50%",
                  width: 6,
                  height: 18,
                  backgroundColor: buttonColor,
                  borderRadius: 3,
                  transform: `translate(-50%, -50%) translate(${x}px, ${y}px) rotate(${angle + 90}deg)`,
                  transformOrigin: "center center",
                  transition: "none",
                }}
              />
            );
          })}
        </div>

        {/* The Animating Button */}
        <div
          style={{
            width: "100%",
            backgroundColor: buttonColor,
            color: textColor,
            padding: "36px 20px",
            borderRadius: 24,
            textAlign: "center",
            fontWeight: "700",
            fontSize: "calc(1.8rem + 1.2vw)",
            boxShadow: "0px 15px 35px rgba(0, 0, 0, 0.35)",
            transform: `scale(${buttonScale})`,
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
            userSelect: "none",
            border: "1px solid rgba(255, 255, 255, 0.15)",
            transition: "none",
          }}
        >
          {buttonText}
        </div>
      </div>

      {/* Dynamic Cursor & Click Spark FX Overlay */}
      <AbsoluteFill style={{ pointerEvents: "none" }}>
        {/* Sparkles Overlay relative to Clicking Spot */}
        {frame >= clickStart && (
          <div
            style={{
              position: "absolute",
              left: targetX,
              top: targetY,
              width: 0,
              height: 0,
              display: "flex",
              justifyContent: "center",
              alignItems: "center",
              opacity: sparkOpacity,
              transition: "none",
            }}
          >
            {/* Outer expanding shock ring */}
            <div
              style={{
                position: "absolute",
                width: sparkRadius * 2,
                height: sparkRadius * 2,
                borderRadius: "50%",
                border: `3px solid ${buttonColor}`,
                transform: "translate(-50%, -50%) scale(1)",
                opacity: interpolate(clickProgress, [0, 0.8], [0.8, 0]),
                transition: "none",
              }}
            />
            {/* Individual spark rays */}
            {sparkAngles.map((angle, index) => {
              const rad = (angle * Math.PI) / 180;
              const distance = sparkRadius * 1.1;
              const x = Math.cos(rad) * distance;
              const y = Math.sin(rad) * distance;
              return (
                <div
                  key={index}
                  style={{
                    position: "absolute",
                    width: 4,
                    height: 14,
                    borderRadius: 2,
                    backgroundColor: buttonColor,
                    transform: `translate(-50%, -50%) translate(${x}px, ${y}px) rotate(${angle + 90}deg)`,
                    transition: "none",
                  }}
                />
              );
            })}
          </div>
        )}

        {/* Vector Mouse Cursor */}
        <div
          style={{
            position: "absolute",
            left: cursorX,
            top: cursorY,
            transform: `translate(-4px, -4px) scale(${cursorScale})`,
            transformOrigin: "top left",
            filter: "drop-shadow(3px 8px 10px rgba(0,0,0,0.45))",
            transition: "none",
          }}
        >
          <svg
            width="64"
            height="64"
            viewBox="0 0 64 64"
            fill="none"
            xmlns="http://www.w3.org/2000/svg"
            style={{ display: "block" }}
          >
            <path
              d="M3 3V49.35L17.75 35.85L29.6 59L39.1 54.1L27.4 31.1L43.8 31.1L3 3Z"
              fill="white"
              stroke="#030816"
              strokeWidth="5"
              strokeLinejoin="miter"
            />
          </svg>
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default ButtonClickAnimation;